import { useCurrentFrame, useVideoConfig, spring, interpolate, Easing } from "remotion";
import timing from "./timing.json";

// Cue timeline generated by scripts/voiceover.mjs from script.json.
// Every scene reveals its pieces on these cues, never before the VO names them.

export const FPS = 30;
export const XFADE = 15; // frames of overlap between scenes

export type Cue = { text: string; src: string; start: number; dur: number };
export type FrameTiming = { id: string; duration: number; cues: Cue[] };

export const FRAMES = timing.frames as FrameTiming[];

// Every scene but the last is extended by the overlap so the VO never plays
// under a transition.
export const sceneFrames = (i: number) =>
  Math.ceil(FRAMES[i].duration * FPS) + (i < FRAMES.length - 1 ? XFADE : 0);

// Absolute start frame of scene i inside the TransitionSeries.
export const sceneStart = (i: number) => {
  let s = 0;
  for (let k = 0; k < i; k++) s += sceneFrames(k) - XFADE;
  return s;
};

export const TOTAL_FRAMES = sceneStart(FRAMES.length - 1) + sceneFrames(FRAMES.length - 1);

export const frameTiming = (id: string) => {
  const f = FRAMES.find((x) => x.id === id);
  if (!f) throw new Error(`no timing for frame ${id}`);
  return f;
};

// Local frame (relative to the scene) at which cue `i` starts / ends.
// `offset` in seconds lets a reveal land on a word inside the cue.
export const cueFrame = (id: string, i: number, offset = 0) =>
  Math.round((frameTiming(id).cues[i].start + offset) * FPS);
export const cueEndFrame = (id: string, i: number) => {
  const c = frameTiming(id).cues[i];
  return Math.round((c.start + c.dur) * FPS);
};

// Local frame at which a given word inside cue `i` is (approximately) spoken.
// Words are weighted by length so the estimate tracks the caption highlight.
// `word` is matched case-insensitively against the cue text with punctuation
// stripped; `nth` picks a repeated word. Falls back to the cue start.
export const wordFrame = (id: string, i: number, word: string, nth = 0) => {
  const c = frameTiming(id).cues[i];
  const words = c.text.split(" ");
  const norm = (w: string) => w.replace(/[.,?!:;()"']/g, "").toLowerCase();
  const target = norm(word);
  const weights = words.map((w) => w.length + 2);
  const total = weights.reduce((a, b) => a + b, 0);
  let seen = 0;
  let acc = 0;
  for (let k = 0; k < words.length; k++) {
    if (norm(words[k]).startsWith(target)) {
      if (seen === nth) return Math.round((c.start + (acc / total) * c.dur) * FPS);
      seen++;
    }
    acc += weights[k];
  }
  return cueFrame(id, i);
};

// Smooth long-tail settle (critically damped) — the house entrance curve.
export const useReveal = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  return (at: number, durationInFrames = 22) =>
    spring({ frame: frame - at, fps, config: { damping: 200 }, durationInFrames });
};

// power3-out tween from `a` to `b` frames.
export const ease = (frame: number, a: number, b: number, from = 0, to = 1) =>
  interpolate(frame, [a, b], [from, to], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
